///   3. `[]` quote_mint
///   4. `[writable]` bucket_quote_token_account
///   5. `[writable]` withdrawer_quote_token_account
///   6. `[writable]` deposit_pda
///   7. `[writable, signer]` payer
///   8. `[signer, optional]` withdrawer
///   9. `[signer, optional]` backend_signer
///   10. `[writable]` fee_quote_token_account
///   11. `[]` quote_token_program
///   12. `[]` associated_token_program
///   13. `[]` system_program
pub struct WithdrawVaultV2CpiBuilder<'a, 'b> {
    instruction: Box<WithdrawVaultV2CpiBuilderInstruction<'a, 'b>>,
}

impl<'a, 'b> WithdrawVaultV2CpiBuilder<'a, 'b> {
    pub fn new(program: &'b solana_program::account_info::AccountInfo<'a>) -> Self {
        let instruction = Box::new(WithdrawVaultV2CpiBuilderInstruction {
            __program: program,
            genesis_account: None,
            bucket: None,
            base_mint: None,
            quote_mint: None,
            bucket_quote_token_account: None,
            withdrawer_quote_token_account: None,
            deposit_pda: None,
            payer: None,
            withdrawer: None,
            backend_signer: None,
            fee_quote_token_account: None,
            quote_token_program: None,
            associated_token_program: None,
            system_program: None,
            padding: None,
            amount_quote_token: None,
            __remaining_accounts: Vec::new(),
        });
        Self { instruction }
    }
    /// The address of the genesis account
    #[inline(always)]
    pub fn genesis_account(
        &mut self,
        genesis_account: &'b solana_program::account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.genesis_account = Some(genesis_account);
        self
    }
    /// The address of the vault bucket
    #[inline(always)]
    pub fn bucket(
        &mut self,
        bucket: &'b solana_program::account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.bucket = Some(bucket);
        self
    }
    /// The mint account of the base token
    #[inline(always)]
    pub fn base_mint(
        &mut self,
        base_mint: &'b solana_program::account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.base_mint = Some(base_mint);
        self
    }
    /// The mint account of the quote token
    #[inline(always)]
    pub fn quote_mint(
        &mut self,
        quote_mint: &'b solana_program::account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.quote_mint = Some(quote_mint);
        self
    }
    /// The bucket's quote token account
    #[inline(always)]
    pub fn bucket_quote_token_account(
        &mut self,
        bucket_quote_token_account: &'b solana_program::account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.bucket_quote_token_account = Some(bucket_quote_token_account);
        self
    }
    /// The withdrawer's quote token account
    #[inline(always)]
    pub fn withdrawer_quote_token_account(
        &mut self,
        withdrawer_quote_token_account: &'b solana_program::account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.withdrawer_quote_token_account = Some(withdrawer_quote_token_account);
        self
    }
    /// The deposit PDA account
    #[inline(always)]
    pub fn deposit_pda(
        &mut self,
        deposit_pda: &'b solana_program::account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.deposit_pda = Some(deposit_pda);
        self
    }
    /// The account paying for ATA creation and receiving rent from closed deposit PDA
    #[inline(always)]
    pub fn payer(&mut self, payer: &'b solana_program::account_info::AccountInfo<'a>) -> &mut Self {
        self.instruction.payer = Some(payer);
        self
    }
    /// `[optional account]`
    /// The withdrawer's wallet (defaults to payer if not provided)
    #[inline(always)]
    pub fn withdrawer(
        &mut self,
        withdrawer: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    ) -> &mut Self {
        self.instruction.withdrawer = withdrawer;
        self
    }
    /// `[optional account]`
    /// Backend authorization signer
    #[inline(always)]
    pub fn backend_signer(
        &mut self,
        backend_signer: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    ) -> &mut Self {
        self.instruction.backend_signer = backend_signer;
        self
    }
    /// The fee wallet's quote token account
    #[inline(always)]
    pub fn fee_quote_token_account(
        &mut self,
        fee_quote_token_account: &'b solana_program::account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.fee_quote_token_account = Some(fee_quote_token_account);
        self
    }
    /// The SPL Token program for the quote token
    #[inline(always)]
    pub fn quote_token_program(
        &mut self,
        quote_token_program: &'b solana_program::account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.quote_token_program = Some(quote_token_program);
        self
    }
    /// The Associated Token program
    #[inline(always)]
    pub fn associated_token_program(
        &mut self,
        associated_token_program: &'b solana_program::account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.associated_token_program = Some(associated_token_program);
        self
    }
    /// The system program
    #[inline(always)]
    pub fn system_program(
        &mut self,
        system_program: &'b solana_program::account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.system_program = Some(system_program);
        self
    }
    #[inline(always)]
    pub fn padding(&mut self, padding: [u8; 7]) -> &mut Self {
        self.instruction.padding = Some(padding);
        self
    }
    #[inline(always)]
    pub fn amount_quote_token(&mut self, amount_quote_token: u64) -> &mut Self {
        self.instruction.amount_quote_token = Some(amount_quote_token);
        self
    }
    /// Add an additional account to the instruction.
    #[inline(always)]
    pub fn add_remaining_account(
        &mut self,
        account: &'b solana_program::account_info::AccountInfo<'a>,
        is_writable: bool,
        is_signer: bool,
    ) -> &mut Self {
        self.instruction
            .__remaining_accounts
            .push((account, is_writable, is_signer));
        self
    }
    /// Add additional accounts to the instruction.
    ///
    /// Each account is represented by a tuple of the `AccountInfo`, a `bool` indicating whether the account is writable or not,
    /// and a `bool` indicating whether the account is a signer or not.
    #[inline(always)]
    pub fn add_remaining_accounts(
        &mut self,
        accounts: &[(
            &'b solana_program::account_info::AccountInfo<'a>,
            bool,
            bool,
        )],
    ) -> &mut Self {
        self.instruction
            .__remaining_accounts
            .extend_from_slice(accounts);
        self
    }
    #[inline(always)]
    pub fn invoke(&self) -> solana_program::entrypoint::ProgramResult {
        self.invoke_signed(&[])
    }
    #[allow(clippy::clone_on_copy)]
    #[allow(clippy::vec_init_then_push)]
    pub fn invoke_signed(
        &self,
        signers_seeds: &[&[&[u8]]],
    ) -> solana_program::entrypoint::ProgramResult {
        let args = WithdrawVaultV2InstructionArgs {
            padding: self
                .instruction
                .padding
                .clone()
                .expect("padding is not set"),
            amount_quote_token: self
                .instruction
                .amount_quote_token
                .clone()
                .expect("amount_quote_token is not set"),
        };
        let instruction = WithdrawVaultV2Cpi {
            __program: self.instruction.__program,

            genesis_account: self
                .instruction
                .genesis_account
                .expect("genesis_account is not set"),

            bucket: self.instruction.bucket.expect("bucket is not set"),

            base_mint: self.instruction.base_mint.expect("base_mint is not set"),

            quote_mint: self.instruction.quote_mint.expect("quote_mint is not set"),

            bucket_quote_token_account: self
                .instruction
                .bucket_quote_token_account
                .expect("bucket_quote_token_account is not set"),

            withdrawer_quote_token_account: self
                .instruction
                .withdrawer_quote_token_account
                .expect("withdrawer_quote_token_account is not set"),

            deposit_pda: self
                .instruction
                .deposit_pda
                .expect("deposit_pda is not set"),

            payer: self.instruction.payer.expect("payer is not set"),

            withdrawer: self.instruction.withdrawer,

            backend_signer: self.instruction.backend_signer,

            fee_quote_token_account: self
                .instruction
                .fee_quote_token_account
                .expect("fee_quote_token_account is not set"),

            quote_token_program: self
                .instruction
                .quote_token_program
                .expect("quote_token_program is not set"),

            associated_token_program: self
                .instruction
                .associated_token_program
                .expect("associated_token_program is not set"),

            system_program: self
                .instruction
                .system_program
                .expect("system_program is not set"),
            __args: args,
        };
        instruction.invoke_signed_with_remaining_accounts(
            signers_seeds,
            &self.instruction.__remaining_accounts,
        )
    }
}

struct WithdrawVaultV2CpiBuilderInstruction<'a, 'b> {
    __program: &'b solana_program::account_info::AccountInfo<'a>,
    genesis_account: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    bucket: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    base_mint: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    quote_mint: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    bucket_quote_token_account: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    withdrawer_quote_token_account: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    deposit_pda: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    payer: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    withdrawer: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    backend_signer: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    fee_quote_token_account: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    quote_token_program: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    associated_token_program: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    system_program: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    padding: Option<[u8; 7]>,
    amount_quote_token: Option<u64>,
    /// Additional instruction accounts `(AccountInfo, is_writable, is_signer)`.
    __remaining_accounts: Vec<(
        &'b solana_program::account_info::AccountInfo<'a>,
        bool,
        bool,
    )>,
}
